            <ListItem key={n.id} as="li" variant={n.read ? "default" : "outline"}>
              <ListItemMedia type="tile" decorative>
                <Icon />
              </ListItemMedia>
              <ListItemContent>
                <ListItemTitle
                  style={{
                    fontWeight: n.read ? "var(--atlas-font-weight-regular)" : "var(--atlas-font-weight-semibold)",
                  }}
                >
                  {n.title}
                </ListItemTitle>
                <ListItemDescription>
                  {n.where} · {n.when}
                </ListItemDescription>
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: "var(--atlas-spacing-2)",
                    marginBlockStart: "var(--atlas-spacing-2)",
                  }}
                >
                  <Badge size="sm" variant={n.read ? "neutral" : "primary"} dot={!n.read}>
                    {n.read ? "Read" : "Unread"}
                  </Badge>
                  {n.kind === "payment" && (
                    <Badge size="sm" variant="danger">
                      Failed
                    </Badge>
                  )}
                  {n.kind === "approval" &&
                    (done ? (
                      <Badge size="sm" variant="success">
                        Approved
                      </Badge>
                    ) : (
                      <Button size="xs" variant="primary" onClick={() => approve(n.id)}>
                        Approve
                      </Button>
                    ))}
                </div>
              </ListItemContent>
              <ListItemActions>
                <Button size="xs" variant="ghost" onClick={() => setRead(n.id, !n.read)}>
                  {n.read ? "Mark as unread" : "Mark as read"}
                </Button>
              </ListItemActions>
            </ListItem>
          )
        })}
      </ul>
    )
  }

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--atlas-spacing-4)",
        padding: "var(--atlas-spacing-4)",
      }}
    >
      <header
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: "var(--atlas-spacing-3)",
        }}
      >
        <h1
          style={{
            margin: 0,
            fontSize: "var(--atlas-text-h1)",
            fontWeight: "var(--atlas-font-weight-bold)",
            color: "var(--atlas-foreground)",
            lineHeight: "var(--atlas-line-height-tight)",
          }}
        >
          Notifications
        </h1>
        <Button variant="outline" size="sm" disabled={loading || failed || unreadCount === 0} onClick={markAllRead}>
          Mark all as read
        </Button>
      </header>

      <Tabs
        variant="pill"
        size="sm"
        activeTab={tab}
        onTabChange={setTab}
        items={[
          { id: "all", label: "All", content: renderList("all") },
          {
            id: "unread",
            label: "Unread",
            badge: loading || failed ? undefined : unreadCount,
            content: renderList("unread"),
          },
        ]}
      />

      <nav
        aria-label="Preview state"
        style={{
          display: "flex",
          flexWrap: "wrap",
          alignItems: "center",
          gap: "var(--atlas-spacing-1)",
          borderBlockStart: "var(--atlas-border-width-1) solid var(--atlas-border-subtle)",
          paddingBlockStart: "var(--atlas-spacing-3)",
        }}
      >
        <span style={{ fontSize: "var(--atlas-text-caption)", color: "var(--atlas-foreground-muted)" }}>
          Preview state:
        </span>
        {SCENARIOS.map((s) => (
          <Button
            key={s.id}
            size="xs"
            variant={scenario === s.id ? "secondary" : "ghost"}
            aria-pressed={scenario === s.id}
            onClick={() => pick(s.id)}
          >
            {s.label}
          </Button>
        ))}
      </nav>
    </div>
  )
}

